mdl = 'demoModel';
new_system(mdl);
open_system(mdl);
add_block('simulink/Sources/Sine Wave', [mdl '/Sine']);
add_block('simulink/Math Operations/Gain', [mdl '/Gain']);
add_block('simulink/Sinks/Scope', [mdl '/Scope']);
set_param([mdl '/Sine'], 'Amplitude', '2', 'Frequency', '3');
set_param([mdl '/Gain'], 'Gain', '0.5');
add_line(mdl, 'Sine/1', 'Gain/1', 'autorouting', 'on');
add_line(mdl, 'Gain/1', 'Scope/1', 'autorouting', 'on');
set_param(mdl, 'StopTime', '10', 'Solver', 'ode45');
save_system(mdl, 'demoModel.slx');
out = sim(mdl);
close_system(mdl, 0);

gains = [0.5 1 2 4];
for k = numel(gains):-1:1
    simIn(k) = Simulink.SimulationInput('myModel');
    simIn(k) = simIn(k).setVariable('Kp', gains(k));
    simIn(k) = simIn(k).setBlockParameter('myModel/Sine', 'Frequency', '5');
    simIn(k) = simIn(k).setModelParameter('StopTime', '30');
end
simOut = parsim(simIn, 'ShowSimulationManager', 'on');
y = simOut(1).logsout.get('y').Values;
plot(y.Time, y.Data);

slbuild('myModel');                       % C code via Coder
exportToFMU2CS('myModel', 'CreateModelAfterGeneratingFMU', 'off');
makehdl('myModel/HDL_Subsystem', 'TargetLanguage', 'VHDL');

dd = Simulink.data.dictionary.create('params.sldd');
sec = getSection(dd, 'Design Data');
addEntry(sec, 'Kp', 4.2);
saveChanges(dd);
set_param('myModel', 'DataDictionary', 'params.sldd');
mw = get_param('myModel', 'ModelWorkspace');
assignin(mw, 'Ts', 0.001);

sfnew('sfDemo');
rt = sfroot;
ch = rt.find('-isa', 'Stateflow.Chart');
s1 = Stateflow.State(ch); s1.Name = 'Off'; s1.Position = [50 50 100 60];
s2 = Stateflow.State(ch); s2.Name = 'On';  s2.Position = [50 160 100 60];
t = Stateflow.Transition(ch);
t.Source = s1; t.Destination = s2; t.LabelString = 'u > 1';
